window.VF2_UNITS = {"3":{"unit":3,"code":"VF2-U03","title":"SCIENCE & TECHNOLOGY","startNumber":37,"endNumber":52,"entries":[{"number":37,"term":"artificial (a) # false (a)","spoken":"artificial , false","ipa":"artificial /ˌɑːrtəˈfɪʃəl/ · false /fɔːls/","type":"adjective · word family","meaning":"nhân tạo, do con người tạo ra # giả hoặc không đúng sự thật","definition":"Artificial means made by people rather than natural; false means not true, genuine, or correct.","note":"artificial là do con người tạo ra thay cho tự nhiên; false là sai hoặc giả, có ý lừa/không đúng sự thật.","example":"The laboratory uses artificial light, but the report rejected the false claim that the results were natural."},{"number":38,"term":"electric (a) ~ electronic (a)","spoken":"electric , electronic","ipa":"electric /ɪˈlɛktrɪk/ · electronic /ˌɪˌlɛˈktrɑːnɪk/","type":"adjective · word family","meaning":"hoạt động bằng điện hoặc thuộc về điện ~ thuộc thiết bị hoặc mạch điện tử","definition":"Electric relates to electricity as power; electronic relates to devices and circuits that process information.","note":"electric mô tả thứ dùng hoặc tạo điện; electronic mô tả thiết bị dùng mạch/linh kiện điện tử.","example":"An electric motor powers the machine, while electronic sensors record its performance."},{"number":39,"term":"award (v,n) ~ reward (v,n)","spoken":"award , reward","ipa":"award /əˈwɔːrd/ · reward /rɪˈwɔːrd/","type":"verb · noun · word family","meaning":"trao giải; giải thưởng cho thành tích ~ thưởng; phần thưởng cho công sức hoặc hành động tốt","definition":"An award recognizes achievement; a reward is given in return for effort, help, or good behaviour.","note":"award gắn với thành tích được công nhận; reward là phần thưởng đáp lại hành động, nỗ lực hoặc thông tin.","example":"The scientist received an award for her discovery and a financial reward for solving the technical problem."},{"number":40,"term":"attempt (v,n) ~ effort (n) · make an attempt ~ make an effort","spoken":"attempt , effort , make an attempt , make an effort","ipa":"attempt /əˈtɛmpt/ · effort /ˈɛfɚt/ · make /meɪk/","type":"verb · noun · word family","meaning":"thử hoặc cố làm; một lần thử ~ sự nỗ lực, công sức · thực hiện một lần thử ~ nỗ lực cố gắng","definition":"An act of trying to do something difficult; effort is the physical or mental energy used.","note":"attempt vừa là động từ vừa là danh từ, chỉ một lần thử hoặc cố làm; effort là danh từ, nhấn mạnh công sức hoặc năng lượng bỏ ra.","example":"The first attempt failed, but the research team made a greater effort during the second trial."},{"number":41,"term":"manage (v) to V ~ succeed (v) in V-ing","spoken":"manage to verb , succeed in doing","ipa":"manage /ˈmænədʒ/ · succeed /səˈksiːd/","type":"verb · phrase / pattern · word family","meaning":"xoay xở làm được việc gì · thành công trong việc làm gì","definition":"Manage to and succeed in both mean to achieve a difficult result, but they use different verb patterns.","note":"manage to V nhấn mạnh làm được việc khó; succeed in V-ing là thành công trong việc làm gì.","example":"The engineers managed to repair the device and succeeded in restoring the lost data."},{"number":42,"term":"observe (v) · observation (n) · observatory (n) · observant (a)","spoken":"observe , observation , observatory , observant","ipa":"observe /əˈbzɝːv/ · observation /ˌɑːbzɚˈveɪʃən/ · observatory /əˈbzɝːvəˌtɔːri/ · observant /əˈbzɝːvənt/","type":"verb · noun · adjective · word family","meaning":"quan sát · sự quan sát, nhận xét · đài quan sát · tinh ý, giỏi quan sát","definition":"To watch or study carefully; the word family includes the act, the place, and the quality of noticing details.","note":"","example":"Researchers observed the planet from an observatory, and their careful observations depended on an observant team."},{"number":43,"term":"revolution (n) · revolutionary (a) · revolutionize (v)","spoken":"revolution , revolutionary , revolutionize","ipa":"revolution /ˌrɛvəˈluːʃən/ · revolutionary /ˌrɛvəˈluːʃəˌnɛri/ · revolutionize /ˌrɛvəˈluːʃəˌnaɪz/","type":"verb · noun · adjective · word family","meaning":"cuộc cách mạng hoặc sự thay đổi lớn · mang tính cách mạng · cách mạng hóa, làm thay đổi hoàn toàn","definition":"A major and often sudden change; revolutionary describes it, and revolutionize means to transform something completely.","note":"","example":"The discovery was revolutionary and may revolutionize the way doctors detect the disease."},{"number":44,"term":"technique (n) · technical (a) · technician (n) # technology (n) · technological (a) · technologist (n)","spoken":"technique , technical , technician , technology , technological , technologist","ipa":"technique /tɛˈkniːk/ · technical /ˈtɛknɪkəl/ · technician /tɛˈknɪʃən/ · technology /tɛˈknɑːlədʒi/ · technological /ˌtɛknəˈlɑːdʒɪkəl/ · technologist /ˌtɛˈknɑːlədʒɪst/","type":"noun · adjective · word family","meaning":"kĩ thuật hoặc phương pháp · thuộc kĩ thuật · kĩ thuật viên # công nghệ · thuộc công nghệ · chuyên gia công nghệ","definition":"A technique is a method; technology is practical scientific knowledge. The related people and adjectives have different uses.","note":"technique là phương pháp/kĩ năng thực hiện; technology là hệ thống công nghệ. technician thực hành kĩ thuật; technologist nghiên cứu/ứng dụng công nghệ.","example":"The technique is easy to learn, but the technology requires a trained technician and specialist knowledge."},{"number":45,"term":"explain (v) · explanation (n) · explicable (a) >< inexplicable (a)","spoken":"explain , explanation , explicable , inexplicable","ipa":"explain /ɪˈkspleɪn/ · explanation /ˌɛkspləˈneɪʃən/ · explicable /ɛˈksplɪkəbəl/ · inexplicable /ˌɪnəˈksplɪsəbəl/","type":"verb · noun · adjective · word family","meaning":"giải thích · lời hoặc sự giải thích · có thể giải thích được · không thể giải thích được","definition":"To make something clear; explicable means understandable, while inexplicable means impossible to explain.","note":"","example":"The sudden change was explicable, but the second result remained inexplicable despite a detailed explanation."},{"number":46,"term":"psychology (n) · psychologist (n)","spoken":"psychology , psychologist","ipa":"psychology /saɪˈkɑːlədʒi/ · psychologist /saɪˈkɑːlədʒəst/","type":"noun · word family","meaning":"tâm lí học · nhà tâm lí học","definition":"The scientific study of the mind and behaviour; a psychologist is a specialist in this field.","note":"","example":"A psychologist used principles from psychology to examine how stress affects memory."},{"number":47,"term":"carry out ~ conduct ~ perform","spoken":"carry out , conduct , perform","ipa":"carry /ˈkæri/ · out /aʊt/ · conduct /kənˈdʌkt/ · perform /pɚˈfɔːrm/","type":"phrasal verb · word family","meaning":"thực hiện, tiến hành","definition":"To complete or perform a task, experiment, study, or procedure.","note":"conduct/carry out thường đi với research, survey, experiment; perform còn đi với task, operation hoặc biểu diễn.","example":"The university conducted the survey, carried out the analysis, and performed the final safety test."},{"number":48,"term":"come up with","spoken":"come up with","ipa":"come /kʌm/ · up /ʌp/","type":"phrasal verb","meaning":"nảy ra ý tưởng…","definition":"To think of and suggest an idea, plan, or solution.","note":"","example":"The design team came up with a practical solution to reduce energy consumption."},{"number":49,"term":"give off ~ emit ~ release","spoken":"give off , emit , release","ipa":"give /ɡɪv/ · off /ɔːf/ · emit /ɪˈmɪt/ · release /riˈliːs/","type":"phrasal verb · word family","meaning":"phát, thải hoặc tỏa ra","definition":"To send out a gas, smell, heat, light, or other substance.","note":"emit trang trọng/khoa học hơn; give off thường dùng cho mùi, nhiệt, ánh sáng; release nhấn mạnh việc cho thoát ra.","example":"The material gives off a strong smell and may release harmful gases when heated."},{"number":50,"term":"work out ~ figure out # find out # sort out","spoken":"work out , figure out , find out , sort out","ipa":"work /wɝːk/ · out /aʊt/ · figure /ˈfɪɡjɚ/ · find /faɪnd/ · sort /sɔːrt/","type":"phrasal verb · word family","meaning":"tìm ra cách giải hoặc hiểu ra ~ tìm được cách giải quyết # phát hiện thông tin # sắp xếp hoặc giải quyết ổn thỏa","definition":"To discover, understand, or solve something through thought or investigation.","note":"work out/figure out là tìm cách hiểu/giải; find out là phát hiện thông tin; sort out là xử lí, sắp xếp cho ổn.","example":"After working out the calculation, the students figured out why the original answer was incorrect."},{"number":51,"term":"narrow down","spoken":"narrow down","ipa":"narrow /ˈnɛroʊ/ · down /daʊn/","type":"phrasal verb","meaning":"thu hẹp (sự lựa chọn…)","definition":"To reduce a number of choices or possibilities.","note":"","example":"The evidence helped investigators narrow down the possible causes from ten to three."},{"number":52,"term":"come off ~ succeed","spoken":"come off , succeed","ipa":"come /kʌm/ · off /ɔːf/ · succeed /səˈksiːd/","type":"phrasal verb · word family","meaning":"thành công, diễn ra như mong đợi","definition":"To happen successfully or produce the intended result.","note":"","example":"The experiment came off successfully because every stage had been carefully planned."}],"pronunciationFocus":[{"entryNumber":40,"points":[{"category":"final-sound","note":"attempt /əˈtɛmpt/: giữ đủ cụm âm cuối /mpt/"}]},{"entryNumber":44,"points":[{"category":"word-stress","note":"technological /ˌtɛknəˈlɑːdʒɪkəl/: trọng âm chính đặt ở /lɑː/"}]},{"entryNumber":46,"points":[{"category":"silent-letter","note":"psychology và psychologist: chữ p đầu không phát âm"},{"category":"word-stress","note":"psychology /saɪˈkɑːlədʒi/: trọng âm chính ở âm tiết thứ hai"}]},{"entryNumber":49,"points":[{"category":"linking","note":"give‿off: nối /v/ sang /ɔː/"}]}]}};
